"""Dry-run of the bundle apply (everything approved) — mirrors bundle.howToApply."""
import json,sys,os
R=sys.argv[1]; B=json.load(open(sys.argv[2])); dec=B.get('approvals',{}).get('decisions') or None
ok=lambda i: (dec is None) or dec.get(i)=='approve'
L=lambda p: json.load(open(os.path.join(R,p))); W=lambda p,d: open(os.path.join(R,p),'w').write(json.dumps(d,indent=1,ensure_ascii=False)+'\n')
for s in B['snapshots']:
    assert not os.path.exists(os.path.join(R,s['path'])), s['path']
    os.makedirs(os.path.dirname(os.path.join(R,s['path'])),exist_ok=True)
    W(s['path'],{k:s[k] for k in ('url','title','retrievedAt','scope','content')})
A={b:L(f'content/paced/{b}/approvals.json') for b in ('2026-11','2026-12')}
for c in B['changes']:
    a=A[c['batch']]; approved=ok(c['id']); removed=(dec or {}).get(c['id'])=='remove'
    if c['kind']=='keep':
        if removed:
            for i in c['ids']: a['decisions'][i]='remove'
        continue
    if not approved: continue
    if c['kind']=='edit':
        for i,s in c['set'].items(): a.setdefault('edits',{}).setdefault(i,{}).update(s)
    elif c['kind']=='hold':
        for i in c['hold']: a.setdefault('held',{})[i]='Nov 22 review ('+c['title']+'): '+c['why'][:200]
    elif c['kind']=='release':
        for i in c['release']: a.get('held',{}).pop(i,None)
        for i,s in (c.get('set') or {}).items(): a.setdefault('edits',{}).setdefault(i,{}).update(s)
    elif c['kind']=='remove':
        for i in c['ids']: a['decisions'][i]='remove'; a.get('held',{}).pop(i,None)
rv=L('content/paced/2026-12/review.json')
for x in B['newItems']:
    if not ok(x['id']): continue
    row={k:v for k,v in x.items() if k not in('batch','added','closerLook')}; rv.append(row); A['2026-12']['decisions'][x['id']]='approve'
    if x.get('holdReason'): A['2026-12'].setdefault('held',{})[x['id']]=x['holdReason']
W('content/paced/2026-12/review.json',rv)
for b,checks in B['planChecks'].items():
    r=L(f'content/paced/{b}/review.json'); m={x['id']:x for x in r}
    for i,c in checks.items():
        if i in m: m[i]['planEvidence']=c['evidence']; m[i]['plan']='confirmed'
    W(f'content/paced/{b}/review.json',r)
for b,a in A.items(): a['reviewedOn']='2026-11-22'; W(f'content/paced/{b}/approvals.json',a)
os.makedirs(os.path.join(R,'content/paced/2027-01'),exist_ok=True)
rows=[]; a3=dict(batch='2027-01',reviewedOn='2026-11-22',reviewPage=B.get('reviewPage'),decisions={},notes={},edits={},held={})
for x in B['drafts']:
    rows.append({k:v for k,v in x.items() if k not in('batch','closerLook')})
    d=(dec or {}).get(x['id'],'approve' if dec is None else None)
    if d: a3['decisions'][x['id']]=d
    if d=='approve' and x['grade']=='K' and x['game']=='spellingBee': a3['held'][x['id']]='Kindergarten photo not made yet (image generation)'
W('content/paced/2027-01/review.json',rows); W('content/paced/2027-01/approvals.json',a3)
print('applied')
